cases.script:
% Supplementary native CK final-pass witness Δ
Create Spacecraft Sat;
Sat.DateFormat = UTCGregorian;
Sat.Epoch = '01 Jan 2000 12:00:00.000';
Sat.CoordinateSystem = EarthMJ2000Eq;
Sat.DisplayStateType = Cartesian;
Sat.X = 7000;
Sat.Y = 0;
Sat.Z = 0;
Sat.VX = 0;
Sat.VY = 7.546053287267836;
Sat.VZ = 0;
Sat.NAIFId = -100057;
Sat.Attitude = Spinner;
Sat.AttitudeCoordinateSystem = EarthMJ2000Eq;
Sat.AttitudeDisplayStateType = EulerAngles;
Sat.EulerAngleSequence = '123';
Sat.EulerAngle1 = 0;
Sat.EulerAngle2 = 0;
Sat.EulerAngle3 = 10;
Sat.AttitudeRateDisplayStateType = AngularVelocity;
Sat.AngularVelocityX = 0;
Sat.AngularVelocityY = 0;
Sat.AngularVelocityZ = 0;
Create ForceModel FM;
FM.PrimaryBodies = {};
FM.PointMasses = {Earth};
FM.SRP = Off;
Create Propagator PropA;
PropA.Type = RungeKutta89;
PropA.FM = FM;
PropA.InitialStepSize = 5;
PropA.MinStep = 5;
PropA.MaxStep = 5;
PropA.Accuracy = 1e-12;
Create EphemerisFile Export;
Export.Spacecraft = Sat;
Export.FileFormat = CK;
Export.StateType = Quaternion;
Export.Filename = '@OUTPUT@/solution.bc';
Export.CoordinateSystem = EarthMJ2000Eq;
Export.StepSize = IntegratorSteps;
Export.InterpolationOrder = 7;
Export.WriteEphemeris = true;
Create Variable U Radius Cost CkHeading;
U = 0;
Radius = 7000;
Cost = 0;
CkHeading = 10;
Create DifferentialCorrector DC;
DC.MaximumIterations = 30;
DC.ReportFile = '@OUTPUT@/target.txt';
Create Yukon Opt;
Opt.MaximumIterations = 50;
Opt.FeasibilityTolerance = 1e-12;
Opt.OptimalityTolerance = 1e-12;
Opt.FunctionTolerance = 1e-12;
Opt.UseCentralDifferences = true;
Opt.ReportFile = '@OUTPUT@/optimizer.txt';
Create ReportFile Trials;
Trials.Filename = '@OUTPUT@/trials.csv';
Trials.SolverIterations = All;
Trials.WriteHeaders = false;
Trials.FixedWidth = false;
Trials.Delimiter = ',';
Trials.Precision = 17;
BeginMissionSequence;
Target 'Final solution only' DC {SolveMode = Solve, ExitMode = SaveAndContinue, ShowProgressWindow = false};
Vary DC(U = 0, {Perturbation = 0.0001, Lower = -2, Upper = 4, MaxStep = 1});
CkHeading = 10 + 20*U;
Sat.EulerAngle3 = CkHeading;
Radius = 7000 + 100*U;
Sat.X = Radius;
Sat.Y = 0;
Sat.Z = 0;
Sat.VX = 0;
Sat.VY = sqrt(398600.4415/Radius);
Sat.VZ = 0;
Propagate 'Trial or final circle' PropA(Sat) {Sat.ElapsedSecs = 120};
Report Trials U Sat.ElapsedSecs Sat.DCM11 Sat.DCM12 Sat.DCM13 Sat.DCM21 Sat.DCM22 Sat.DCM23 Sat.DCM31 Sat.DCM32 Sat.DCM33 Sat.EarthMJ2000Eq.X Sat.EarthMJ2000Eq.Y Sat.EarthMJ2000Eq.Z Sat.EarthMJ2000Eq.VX Sat.EarthMJ2000Eq.VY Sat.EarthMJ2000Eq.VZ;
Achieve DC(U = 2, {Tolerance = 0.0000000001});
EndTarget;

